{
	"name": "ocx",
	"version": "2.0.15",
	"description": "OCX CLI - OpenCode extension manager with portable, isolated profiles. Your setup, anywhere.",
	"author": "kdcokenny",
	"license": "MIT",
	"type": "module",
	"main": "./dist/index.js",
	"bin": {
		"ocx": "./dist/index.js"
	},
	"files": [
		"dist/index.js"
	],
	"publishConfig": {
		"access": "public"
	},
	"repository": {
		"type": "git",
		"url": "https://github.com/kdcokenny/ocx.git"
	},
	"homepage": "https://github.com/kdcokenny/ocx#readme",
	"bugs": {
		"url": "https://github.com/kdcokenny/ocx/issues"
	},
	"keywords": [
		"opencode",
		"cli",
		"extensions",
		"agents",
		"plugins",
		"mcp",
		"shadcn",
		"registry"
	],
	"engines": {
		"bun": ">=1.2.0"
	},
	"scripts": {
		"build": "bun run scripts/build.ts",
		"build:binary": "bun run scripts/build-binary.ts",
		"build:binary:all": "bun run scripts/build-binary.ts --all",
		"build:binary:windows": "bun run scripts/build-binary.ts --target=windows-x64 && bun run scripts/build-binary.ts --target=windows-x64-baseline",
		"release:tag": "bun run scripts/release-tag.ts",
		"check": "bun check:biome && bun check:types",
		"check:biome": "biome check .",
		"check:types": "tsc --noEmit",
		"dev": "bun run src/index.ts",
		"prepublishOnly": "bun run build",
		"test": "bun test",
		"test:binary-smoke": "OCX_DIST_TESTS=1 bun test tests/binary-smoke.test.ts"
	},
	"dependencies": {
		"commander": "^14.0.3",
		"fuzzysort": "^3.1.0",
		"jsonc-parser": "3.3.1",
		"kleur": "^4.1.5",
		"ora": "^9.3.0",
		"remeda": "^2.33.7",
		"zod": "^4.3.6"
	},
	"devDependencies": {
		"@types/bun": "^1.3.11"
	}
}
